try{mkdir(dirname(kalite_filo_admin_vehicle_store_path()),0700,true);file_put_contents(kalite_filo_admin_vehicle_store_path(),'{}');file_put_contents(kalite_filo_admin_article_store_path(),'{}');$_SESSION['identity']=['id'=>'owner'];$changes=kalite_filo_admin_unpublished_changes();publish_assert(count($changes)===2,'Only existing private stores must appear as unpublished changes.');$request=kalite_filo_admin_create_staging_publish_request();publish_assert($request['status']==='awaiting_runner'&&$request['target']==='staging'&&strlen($request['snapshotHash'])===64,'Staging request must freeze a runner-pending snapshot.');$safe=kalite_filo_admin_safe_publish_request($request);publish_assert(!array_key_exists('snapshot',$safe)&&$safe['changeCount']===2,'Browser history must not expose the private snapshot.');publish_assert(count(kalite_filo_admin_publish_requests())===1,'Private request history must round-trip.');}finally{publish_remove($root);}fwrite(STDOUT,"Admin publishing store tests passed.\n");
